#include <cassert>
#include <fstream>
#include <thread>
#include <chrono>
#include <algorithm>
using namespace Bazzalt;
struct CancelOnApply:Component{};
int main(){
 auto folder=std::filesystem::temp_directory_path()/("bazzalt-world-"+UUID::Generate().ToString());std::filesystem::create_directories(folder/"Assets");
 {std::ofstream out(folder/"Game.bproject");out<<"FormatVersion: 1\nProjectUUID: "<<UUID::Generate().ToString()<<"\nName: World\nAssetDirectory: Assets\nStartupScene: ''\nProperties: {}\n";}
 {
 Runtime::Engine engine;Scene a,b;Entity parent;for(unsigned i=0;i<12;++i){auto e=a.CreateEntity(UUID{201,i+1},"Chunk A");if(parent)e.SetParent(parent,false);parent=e;}b.CreateEntity(UUID{202,1},"Chunk B");assert(engine.SaveSceneAsset(a,folder/"Assets/A.bscene"));assert(engine.SaveSceneAsset(b,folder/"Assets/B.bscene"));assert(engine.LoadProject(folder/"Game.bproject",false));assert(engine.Init(true,false));auto keep=engine.GetScene().CreateEntity("Persistent object");auto keepId=keep.GetUUID();
 auto assetA=AssetManager::GetAsset(folder/"Assets/A.bscene"),assetB=AssetManager::GetAsset(folder/"Assets/B.bscene");assert(assetA&&assetB);auto settings=SceneManager::GetStreamingSettings();settings.EntitiesPerTick=1;settings.MaxResidentCells=1;settings.RetryDelaySeconds=.1f;SceneManager::SetStreamingSettings(settings);
 auto tick=[&]{engine.Update(false);std::this_thread::sleep_for(std::chrono::milliseconds(1));};
 auto info=[&](UUID id){for(auto& cell:SceneManager::GetStreamingCells())if(cell.SceneAsset==id)return cell;return StreamingCellInfo{};};
 auto until=[&](auto predicate){for(unsigned i=0;i<5000&&!predicate();++i)tick();assert(predicate());};
 StreamingGrid grid;grid.CellSize={100,100,100};grid.LoadDistance=10;grid.UnloadDistance=20;grid.Cells={{assetA->Id,0,0,0},{assetB->Id,10,0,0}};assert(grid.IsValid());auto invalid=grid;invalid.Cells[1].X=0;assert(!invalid.IsValid());assert(!SceneManager::RegisterStreamingGrid(invalid));assert(SceneManager::GetStreamingCells().empty());assert(SceneManager::RegisterStreamingGrid(grid));assert(!SceneManager::RegisterStreamingGrid(grid));
 auto sourceA=UUID::Generate(),sourceB=UUID::Generate();SceneManager::SetStreamingSource(sourceA,{60,0,0});SceneManager::SetStreamingSource(sourceB,{1000,0,0});until([&]{return info(assetB->Id).Status==AsyncLoadStatus::Complete;});assert(info(assetA->Id).Status==AsyncLoadStatus::Unloaded);assert(SceneManager::GetStreamingStatistics().ResidentCells==1);assert(SceneManager::GetStreamingStatistics().Sources==2);
 assert(SceneManager::RemoveStreamingSource(sourceB));until([&]{return info(assetA->Id).Status==AsyncLoadStatus::Complete;});assert(info(assetB->Id).Status==AsyncLoadStatus::Unloaded);auto root=engine.GetScene().GetEntity(info(assetA->Id).RootUUID);assert(root);keep.SetParent(engine.GetScene().GetEntity(UUID{201,1}),true);
 SceneManager::SetStreamingSource(sourceB,{40,0,0});SceneManager::RemoveStreamingSource(sourceA);for(unsigned i=0;i<3;++i)tick();assert(info(assetA->Id).Status==AsyncLoadStatus::Complete);SceneManager::SetStreamingSource(sourceB,{69,0,0});tick();assert(info(assetA->Id).Status==AsyncLoadStatus::Complete);
 auto before=engine.GetScene().GetEntityCount();SceneManager::SetStreamingSource(sourceB,{71,0,0});tick();assert(info(assetA->Id).Status==AsyncLoadStatus::Unloading);assert(engine.GetScene().GetEntityCount()+1>=before);bool sawUnload=false;for(auto& event:SceneManager::GetStreamingEvents())sawUnload|=event.SceneAsset==assetA->Id&&event.Status==AsyncLoadStatus::Unloading;assert(sawUnload);
 until([&]{return info(assetA->Id).Status==AsyncLoadStatus::Unloaded;});assert(engine.GetScene().GetEntity(keepId));assert(engine.GetScene().GetEntity(keepId).GetParent().GetUUID().IsRoot());assert(engine.GetScene().GetEntityCount()==2);SceneManager::RemoveStreamingSource(sourceB);
 // A failed cell remains inspectable, retries explicitly, and does not poison the queue.
 std::ifstream input(assetA->CachePath,std::ios::binary);std::string contents((std::istreambuf_iterator<char>(input)),{});input.close();{std::ofstream out(assetA->CachePath,std::ios::binary);out<<"InvalidScene: true\n";}SceneManager::SetStreamingSource(sourceA,{0,0,0});until([&]{return info(assetA->Id).Status==AsyncLoadStatus::Failed;});assert(!info(assetA->Id).Error.empty());{std::ofstream out(assetA->CachePath,std::ios::binary);out<<contents;}assert(SceneManager::RetryStreamingCell(assetA->Id));until([&]{return info(assetA->Id).Status==AsyncLoadStatus::Complete;});SceneManager::RemoveStreamingSource(sourceA);until([&]{return info(assetA->Id).Status==AsyncLoadStatus::Unloaded;});assert(SceneManager::UnregisterStreamingCell(assetA->Id));assert(SceneManager::UnregisterStreamingCell(assetB->Id));tick();
 // Persistent-scene components author streaming without a user-owned loop.
 auto definition=engine.GetScene().CreateEntity("Cell definition");definition.GetComponent<Transform>().Position={200,0,0};auto& cell=definition.AddComponent<WorldCell>();cell.SceneAsset=assetA->Id;cell.HalfExtents={10,10,10};cell.LoadDistance=1;cell.UnloadDistance=2;
 auto source=engine.GetScene().CreateEntity("Player streaming source");source.GetComponent<Transform>().Position={211,0,0};source.AddComponent<StreamingSource>();assert(engine.SaveSceneAsset(engine.GetScene(),folder/"Assets/World.bscene"));assert(engine.RefreshAssets());auto world=AssetManager::GetAsset(folder/"Assets/World.bscene");assert(world);auto dependencies=AssetManager::GetDependencies(world->Id);assert(std::find(dependencies.begin(),dependencies.end(),assetA->Id)!=dependencies.end());auto restored=engine.LoadSceneAsset(folder/"Assets/World.bscene");assert(restored&&restored->GetEntity(definition.GetUUID()).GetComponent<WorldCell>().SceneAsset==assetA->Id);assert(restored->GetEntity(source.GetUUID()).HasComponent<StreamingSource>());
 assert(engine.StartScripts());until([&]{return info(assetA->Id).Status==AsyncLoadStatus::Complete;});assert(engine.GetScene().GetEntity(info(assetA->Id).RootUUID).GetComponent<Transform>().Position.X==200);source.GetComponent<StreamingSource>().Enabled=false;until([&]{return info(assetA->Id).Status==AsyncLoadStatus::Unloaded;});cell.AlwaysLoaded=true;until([&]{return info(assetA->Id).Status==AsyncLoadStatus::Complete;});
 definition.GetComponent<Transform>().Position.X=220;tick();assert(engine.GetScene().GetEntity(info(assetA->Id).RootUUID).GetWorldTransform().Position.X==220);auto duplicate=engine.GetScene().CreateEntity("Duplicate invalid definition");duplicate.AddComponent<WorldCell>()=cell;until([&]{return !engine.GetScene().GetEntity(UUID{201,1});});assert(!engine.GetScene().GetEntity(UUID{201,2}));engine.GetScene().DestroyEntity(duplicate);until([&]{return info(assetA->Id).Status==AsyncLoadStatus::Complete;});cell.Enabled=false;until([&]{return !engine.GetScene().GetEntity(UUID{201,1});});for(unsigned i=0;i<20;++i)tick();assert(!engine.GetScene().GetEntity(UUID{201,2}));engine.StopScripts();engine.GetScene().DestroyEntity(source);engine.GetScene().DestroyEntity(definition);
 // Explicit cancellation at replacement activation must never destroy matching live UUIDs.
 auto live=engine.GetScene().CreateEntity(UUID{203,1},"Live survivor");SceneLoadHandle request;engine.GetSceneSerializer().GetComponents().Register<CancelOnApply>("Test.CancelOnApply",1,[](const CancelOnApply&,PropertyMap&){},[&](CancelOnApply&,const PropertyMap&,std::uint32_t){assert(request.Cancel());return true;});Scene replacement;replacement.CreateEntity(live.GetUUID(),"Replacement copy").AddComponent<CancelOnApply>();assert(engine.SaveSceneAsset(replacement,folder/"Assets/Replacement.bscene"));request=SceneManager::LoadSceneAsync(folder/"Assets/Replacement.bscene");until([&]{return request.IsDone();});assert(request.GetStatus()==AsyncLoadStatus::Cancelled);tick();assert(engine.GetScene().GetEntity(live.GetUUID()).GetComponent<Name>().Value=="Live survivor");engine.Shutdown(true);Jobs::WaitAll();
 }
 std::filesystem::remove_all(folder);
}
